function script:qs_intro {
  q_say 'You did it: your own apartment. The movers came, carried everything up three flights of stairs, and left it all in a heap in the hallway. Your friend Jo helped, but had to run. Jo left you a note.

Read it first:  Get-Content welcome-home.txt'
}

function script:qs_layout {
  q_mkdir 'bedroom'
  q_mkdir 'mailbox'
}

function script:qs_processes {
  $null = $null
}

function script:qs_fire([string]$on, [string]$key) {
  switch -Exact ("${on}:$key") {
    'enter:hallway' {
      if ((q_trigger_ready 0 $false)) {
        q_trigger_mark 0
        q_say 'Boxes everywhere. You can barely see the floor.'
      }
    }
  }
}

function script:qs_rules {
  $fired = $false
  if ((q_rule_ready 0) -and ((q_exists 'mailbox/spare-key.txt') -and (-not (q_exists 'hallway/spare-key.txt')))) {
    q_rule_mark 0
    $fired = $true
    q_say 'Hmm: you MOVED your only key to the mailbox. Move-Item moves a thing; Copy-Item makes a copy and leaves the first one where it was. Move it back and copy it instead.'
  }
  if ((q_rule_ready 1) -and ((q_exists 'todo.txt') -and (-not (q_contains 'todo.txt' 'find the remote')))) {
    q_rule_mark 1
    $fired = $true
    q_say 'Uh oh: the old to-do list is gone. Writing with > (or Set-Content) replaces a whole file; >> (or Add-Content) adds to the end. Lesson learned, and no harm done this time.'
  }
  return $fired
}

