function script:qs_goal_teach([string]$id) {
  switch -Exact ($id) {
    'list' {
      q_say 'Get-Content -TotalCount 10 shows just the first 10 lines of a file (-Head and -First work too), so you get the important part of a long file. Its partner, -Tail, shows the last lines.'
    }
    'shelf' {
      q_say 'New-Item -ItemType Directory makes a new folder. New-Item -ItemType Directory living-room\bookshelf makes a folder called bookshelf inside the living room. (mkdir works in PowerShell too: it is a shortcut for exactly this.)'
    }
    'books' {
      q_say 'Move-Item moves things: Move-Item WHAT WHERE. A * is a wildcard: it stands for "anything", so hallway\box-books\*.book means every file in that box ending in .book. One command moves all four.'
    }
    'kitchen' {
      q_say 'A * on its own means everything in a folder. Move-Item hallway\box-kitchen\* kitchen\ empties the whole box into the kitchen.'
    }
    'key' {
      q_say 'Copy-Item copies: the key ends up in the mailbox AND stays in the hallway. Move-Item would have moved your only key.'
    }
    'trash' {
      q_say 'Remove-Item removes files; name several at once with commas between them. Careful: there is no recycle bin in a terminal. Removed means gone.'
    }
    'boxes' {
      q_say 'Remove-Item removes an empty folder straight away. For a folder with things in it, PowerShell asks first, unless you add -Recurse (so double-check before you do).'
    }
    'sign' {
      q_say 'Set-Content writes words into a file, making it if it is new: Set-Content door-sign.txt "Welcome to my place". (Careful: it replaces whatever the file had. "text" > file does the same.)'
    }
    'todo' {
      q_say 'Add-Content adds a line to the end of a file and keeps what was there. Set-Content would have wiped the list.'
    }
  }
}

