function script:qs_goal_solution([string]$id) {
  switch -Exact ($id) {
    'list' {
      return ,@('Get-Content hallway\packing-list.txt -TotalCount 10')
    }
    'shelf' {
      return ,@('New-Item -ItemType Directory living-room\bookshelf')
    }
    'books' {
      return ,@('Move-Item hallway\box-books\*.book living-room\bookshelf\')
    }
    'kitchen' {
      return ,@('Move-Item hallway\box-kitchen\* kitchen\')
    }
    'key' {
      return ,@('Copy-Item hallway\spare-key.txt mailbox\')
    }
    'trash' {
      return ,@('Remove-Item hallway\broken-vase.txt, hallway\bubble-wrap.txt')
    }
    'boxes' {
      return ,@('Remove-Item hallway\box-books, hallway\box-kitchen')
    }
    'sign' {
      return ,@('Set-Content door-sign.txt "Welcome to my place"')
    }
    'todo' {
      return ,@('Add-Content todo.txt "- water the plants"')
    }
  }
}

function script:qs_finish_when {
  return [bool]((q_goal 'books') -and (q_goal 'kitchen') -and (q_goal 'key') -and (q_goal 'trash') -and (q_goal 'boxes') -and (q_goal 'sign') -and (q_goal 'todo'))
}

function script:qs_finish_text {
  q_say 'You flop onto the couch. The books are on the shelf, the kettle is in the kitchen, the neighbor has a key, and the hallway is clear. Home.

You can now make folders and files (New-Item -ItemType Directory, New-Item), move and copy them (Move-Item, Copy-Item), throw them out (Remove-Item), work on many at once with *, and write into files. That''s most of what people do in a terminal every day.'
}

